//! Assembling the generated files.
//!
//! Each file is built as a `ruff_python_ast::ModModule` and handed to
//! [`python::render`]. Nothing here writes Python by hand, so the only thing to
//! get right is the tree.
//!
//! The header is the one exception, and a structural one: ruff's AST has
//! nowhere to put a `#` comment, since `format_module_ast` recovers comments
//! from byte ranges into the *source text*. So the banner is prepended to the
//! formatted output, and everything the tree can express goes through the tree —
//! documentation included, as a docstring rather than a comment.

mod models;

use anyhow::Result;
use ruff_python_ast as ast;

use crate::config::{ClassStyle, Config};
use crate::plugin;
use crate::python::{self, Import};
use crate::schema::Schema;

/// Renders every file a codegen entry asked for.
pub fn files(
    schema: &Schema,
    config: &Config,
    request: &plugin::GenerateRequest,
) -> Result<Vec<plugin::File>> {
    let mut files = Vec::new();
    if config.models.emit {
        files.push(models::module(schema, config, request)?);
    }
    Ok(files)
}

/// The banner every generated file opens with.
///
/// Recording the versions makes a regenerated file's diff explain itself,
/// though `omit_sqlc_version` drops the sqlc line for anyone who would rather
/// not see churn on every upgrade.
fn header(request: &plugin::GenerateRequest, config: &Config) -> String {
    let (name, version) = (env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION"));
    let sqlc = match config.omit_sqlc_version || request.sqlc_version.is_empty() {
        true => String::new(),
        false => format!("#   sqlc {}\n", request.sqlc_version),
    };
    format!(
        "# Code generated by {name}. DO NOT EDIT.\n\
         # versions:\n\
         #   {name} v{version}\n\
         {sqlc}"
    )
}

/// How a data class is declared in the configured style.
///
/// Both styles say the same thing — a record of typed fields — so only the
/// shape differs, and each contributes exactly one of the two positions.
struct ClassShape {
    decorator: Option<ast::Expr>,
    base: Option<ast::Expr>,
    import: Import,
}

impl ClassShape {
    fn of(style: ClassStyle) -> Self {
        match style {
            ClassStyle::Dataclass => Self {
                decorator: Some(python::expr("dataclasses.dataclass()")),
                base: None,
                import: Import::module("dataclasses"),
            },
            ClassStyle::Pydantic => Self {
                decorator: None,
                base: Some(python::expr("pydantic.BaseModel")),
                import: Import::module("pydantic"),
            },
        }
    }
}
